// Builds the generated parts of the plugins:
//   plugins/claude/server/ccb-mcp.mjs  ccb-mcp and its dependencies in one file, runnable with plain Node
//   plugins/claude/hooks/core/         a copy of @ccb/core's compiled output (a mod can import only its own files)
//   plugins/codex/server/ccb-mcp.mjs   the same server bundle, for the Codex plugin
//   plugins/claude/skills/             the Codex plugin's skills, so Claude Code gets the same
//                                      /prompt-buttons:<skill> commands; they work in cloud sessions,
//                                      where the app doesn't show the button row
// Usage: node scripts/build-plugin.mjs          write the files
//        node scripts/build-plugin.mjs --check  fail if the committed files are out of date
import { mkdtemp, mkdir, readdir, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, relative } from "node:path";
import { fileURLToPath } from "node:url";
import { build } from "esbuild";

const root = fileURLToPath(new URL("..", import.meta.url));
const plugin = join(root, "plugins", "claude");
const codexServer = join(root, "plugins", "codex", "server", "ccb-mcp.mjs");
const codexSkills = join(root, "plugins", "codex", "skills");
// The Codex skills shared with Claude Code (the generated $ccb-* skills are Codex-only).
const SHARED_SKILLS = ["continue", "regenerate-prompt", "prompt-bank", "notes", "translate", "drive-sync", "button"];
const check = process.argv.includes("--check");
const HEADER = "// Generated by scripts/build-plugin.mjs from packages/core. Do not edit; run `npm run build:plugin`.\n";

async function generate(out) {
  // 1. The server bundle.
  await build({
    entryPoints: [join(root, "packages", "mcp-server", "dist", "bin.js")],
    outfile: join(out, "server", "ccb-mcp.mjs"),
    bundle: true,
    platform: "node",
    format: "esm",
    target: "node22",
    minify: true,
    keepNames: true,
    legalComments: "inline",
    banner: {
      js: "// Generated by scripts/build-plugin.mjs from packages/mcp-server. Do not edit; run `npm run build:plugin`.\nimport { createRequire as __ccbCreateRequire } from 'node:module'; const require = __ccbCreateRequire(import.meta.url);",
    },
    logLevel: "warning",
  });
  // 2. The vendored core: .js and .d.ts files only.
  const from = join(root, "packages", "core", "dist");
  const to = join(out, "hooks", "core");
  async function copyDir(dir) {
    for (const entry of await readdir(dir, { withFileTypes: true })) {
      const path = join(dir, entry.name);
      if (entry.isDirectory()) {
        await copyDir(path);
      } else if (/\.(js|d\.ts)$/.test(entry.name)) {
        const target = join(to, relative(from, path));
        await mkdir(join(target, ".."), { recursive: true });
        const text = (await readFile(path, "utf8")).replace(/\n\/\/# sourceMappingURL=.*$/m, "");
        await writeFile(target, HEADER + text);
      }
    }
  }
  await copyDir(from);
  // 3. The shared skills, copied unchanged.
  for (const name of SHARED_SKILLS) {
    await mkdir(join(out, "skills", name), { recursive: true });
    await writeFile(join(out, "skills", name, "SKILL.md"), await readFile(join(codexSkills, name, "SKILL.md")));
  }
}

async function listFiles(dir, base = dir) {
  const out = [];
  for (const entry of await readdir(dir, { withFileTypes: true }).catch(() => [])) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) out.push(...(await listFiles(path, base)));
    else out.push(relative(base, path));
  }
  return out.sort();
}

const GENERATED = ["server", join("hooks", "core"), "skills"];

if (check) {
  const tmp = await mkdtemp(join(tmpdir(), "ccb-plugin-"));
  try {
    await generate(tmp);
    const problems = [];
    for (const part of GENERATED) {
      const want = await listFiles(join(tmp, part));
      const have = await listFiles(join(plugin, part));
      for (const f of new Set([...want, ...have])) {
        const a = await readFile(join(tmp, part, f), "utf8").catch(() => null);
        const b = await readFile(join(plugin, part, f), "utf8").catch(() => null);
        if (a !== b) problems.push(join(part, f));
      }
    }
    const bundle = await readFile(join(tmp, "server", "ccb-mcp.mjs"), "utf8");
    if ((await readFile(codexServer, "utf8").catch(() => null)) !== bundle) problems.push("plugins/codex/server/ccb-mcp.mjs");
    if (problems.length) {
      console.error(`plugins/claude has out-of-date generated files:\n  ${problems.join("\n  ")}\nRun: npm run build && npm run build:plugin`);
      process.exit(1);
    }
    console.log("Generated plugin files are up to date.");
  } finally {
    await rm(tmp, { recursive: true, force: true });
  }
} else {
  for (const part of GENERATED) await rm(join(plugin, part), { recursive: true, force: true });
  await generate(plugin);
  await mkdir(join(codexServer, ".."), { recursive: true });
  await writeFile(codexServer, await readFile(join(plugin, "server", "ccb-mcp.mjs")));
  console.log("Built plugins/claude/server/ccb-mcp.mjs, plugins/claude/hooks/core/, plugins/claude/skills/ and plugins/codex/server/ccb-mcp.mjs.");
}
